CREATE TABLE public.service_profiles (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', service text NOT NULL DEFAULT '', bio text NOT NULL DEFAULT '', photo_path text NOT NULL DEFAULT '', published boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.service_profiles TO authenticated; GRANT SELECT ON public.service_profiles TO anon; GRANT ALL ON public.service_profiles TO service_role;
ALTER TABLE public.service_profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY service_profile_read ON public.service_profiles FOR SELECT TO anon,authenticated USING (published OR auth.uid()=user_id);
CREATE POLICY service_profile_write ON public.service_profiles FOR ALL TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
CREATE TABLE public.service_photos(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.service_profiles(user_id) ON DELETE CASCADE, path text NOT NULL, caption text NOT NULL DEFAULT '');
GRANT SELECT,INSERT,DELETE ON public.service_photos TO authenticated; GRANT SELECT ON public.service_photos TO anon; GRANT ALL ON public.service_photos TO service_role;
ALTER TABLE public.service_photos ENABLE ROW LEVEL SECURITY;
CREATE POLICY service_photos_read ON public.service_photos FOR SELECT TO anon,authenticated USING(EXISTS(SELECT 1 FROM public.service_profiles p WHERE p.user_id=service_photos.user_id AND (p.published OR p.user_id=auth.uid())));
CREATE POLICY service_photos_insert ON public.service_photos FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND path LIKE auth.uid()::text||'/%');
CREATE POLICY service_photos_delete ON public.service_photos FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.service_reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), profile_id uuid NOT NULL REFERENCES public.service_profiles(user_id) ON DELETE CASCADE, author_id uuid NOT NULL, rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5), body text NOT NULL CHECK(length(body) BETWEEN 3 AND 1000), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(profile_id,author_id), CHECK(profile_id<>author_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.service_reviews TO authenticated; GRANT SELECT ON public.service_reviews TO anon; GRANT ALL ON public.service_reviews TO service_role;
ALTER TABLE public.service_reviews ENABLE ROW LEVEL SECURITY;
CREATE POLICY service_reviews_read ON public.service_reviews FOR SELECT TO anon,authenticated USING(EXISTS(SELECT 1 FROM public.service_profiles p WHERE p.user_id=profile_id AND p.published));
CREATE POLICY service_reviews_write ON public.service_reviews FOR ALL TO authenticated USING(author_id=auth.uid()) WITH CHECK(author_id=auth.uid() AND profile_id<>auth.uid() AND EXISTS(SELECT 1 FROM public.service_profiles p WHERE p.user_id=profile_id AND p.published));
CREATE TABLE public.service_likes(profile_id uuid NOT NULL REFERENCES public.service_profiles(user_id) ON DELETE CASCADE, user_id uuid NOT NULL, PRIMARY KEY(profile_id,user_id));
GRANT SELECT,INSERT,DELETE ON public.service_likes TO authenticated; GRANT ALL ON public.service_likes TO service_role;
ALTER TABLE public.service_likes ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_service_like ON public.service_likes FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.service_profiles p WHERE p.user_id=profile_id AND p.published));
CREATE TABLE public.service_views(profile_id uuid NOT NULL REFERENCES public.service_profiles(user_id) ON DELETE CASCADE, visitor_hash text NOT NULL, day date NOT NULL DEFAULT current_date, PRIMARY KEY(profile_id,visitor_hash,day));
GRANT ALL ON public.service_views TO service_role; ALTER TABLE public.service_views ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.service_profile_data(_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN p.published OR p.user_id=auth.uid() THEN jsonb_build_object('profile',to_jsonb(p),'photos',coalesce((SELECT jsonb_agg(to_jsonb(f)) FROM service_photos f WHERE f.user_id=p.user_id),'[]'::jsonb),'reviews',coalesce((SELECT jsonb_agg(jsonb_build_object('id',r.id,'rating',r.rating,'body',r.body,'created_at',r.created_at) ORDER BY r.created_at DESC) FROM service_reviews r WHERE r.profile_id=p.user_id),'[]'::jsonb),'likes',(SELECT count(*) FROM service_likes l WHERE l.profile_id=p.user_id),'views',(SELECT count(*) FROM service_views v WHERE v.profile_id=p.user_id)) ELSE NULL END FROM service_profiles p WHERE p.user_id=_id $$;
GRANT EXECUTE ON FUNCTION public.service_profile_data(uuid) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.record_service_view(_id uuid,_visitor text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF length(_visitor)=64 AND EXISTS(SELECT 1 FROM service_profiles WHERE user_id=_id AND published) THEN INSERT INTO service_views(profile_id,visitor_hash) VALUES(_id,_visitor) ON CONFLICT DO NOTHING; END IF; END $$;
REVOKE ALL ON FUNCTION public.record_service_view(uuid,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.record_service_view(uuid,text) TO service_role;
CREATE OR REPLACE FUNCTION public.save_service_profile(_name text,_service text,_bio text,_photo text,_published boolean) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF length(_name)>80 OR length(_service)>100 OR length(_bio)>1000 OR (_photo<>'' AND _photo NOT LIKE auth.uid()::text||'/%') THEN RAISE EXCEPTION 'Invalid profile'; END IF; INSERT INTO service_profiles(user_id,display_name,service,bio,photo_path,published) VALUES(auth.uid(),trim(_name),trim(_service),trim(_bio),_photo,_published) ON CONFLICT(user_id) DO UPDATE SET display_name=excluded.display_name,service=excluded.service,bio=excluded.bio,photo_path=excluded.photo_path,published=excluded.published,updated_at=now(); END $$;
GRANT EXECUTE ON FUNCTION public.save_service_profile(text,text,text,text,boolean) TO authenticated;
CREATE POLICY service_file_owner_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='service-photos' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY service_file_owner_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='service-photos' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY service_file_owner_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='service-photos' AND (storage.foldername(name))[1]=auth.uid()::text);